R=Path(__file__).resolve().parents[1];O=R/'sprite-fighter/size-fix-v8';G=R/'sprite-fighter';J=G/'jus-upgrade';E=G/'engine/ikemen-go-v1.0.0/chars';(O/'sprites').mkdir(exist_ok=True)
measurements=json.loads((R/'.tmp/size-redesign/measurements.json').read_text());installed={r['slug']:r for r in json.loads((O/'installation.json').read_text())['fighters']};manifest={r['slug']:r for r in json.loads((J/'manifest.json').read_text())['fighters']};items=[]
for r in measurements:
 slug=r['slug'];row=manifest[slug];n=E/row['engine'];scale=r['air_scale'][1]*r['cns_scale'][1]*320/r['width'];filename=slug+'.png';shutil.copy2(R/r['file'],O/'sprites'/filename)
 item=dict(slug=slug,label=slug.replace('-',' ').title(),neutral=dict(file='sprites/'+filename,axis=r['axis'],scale=scale,height=r['world_height']),role=row['gameplay_size_role'],walk=None)
 p=J/'art'/slug/'packing.json'
 if p.exists():
  d=json.loads(p.read_text());form=J/'art'/slug/'form-cycles-packing.json';folder=f'../jus-upgrade/art/{slug}'
  if form.exists():d=json.loads(form.read_text())['cycles'][0];folder+='/cycles/'+str(d['source_group'])
  # Single-body banks retain the fixed .125 AIR scale; form banks store it.
  airscale=d.get('air_scale',[.125,.125])[1];item['walk']=dict(folder=folder,frames=d['frames'],scale=airscale*r['cns_scale'][1]*320/r['width'])
 elif slug=='cid':
  d=json.loads((G/'characters/cid/art/redesign-v7/installation.json').read_text())['sheets']['movement-a']['frames'][4:]
  item['walk']=dict(folder='../characters/cid/art/redesign-v7/extracted/movement-a',frames=d,indices=list(range(4,12)),scale=d[0]['scale']*r['cns_scale'][1]*320/r['width'])
 items.append(item)
 # Export alternate body references from the installed SFF, keeping actual
 # AIR and CNS scale. This includes small animal/slime/shadow forms.
 forms=installed[slug]['forms'];body={k:v for k,v in forms.items() if int(k)<64150}
 if not body:continue
 source=Sff(n/r['files']['sprite']);air=(n/r['files']['anim']).read_text(encoding='latin1');scales={}
 for line in air.splitlines():
  if re.match(r'^\s*\d+\s*,\s*\d+\s*,',line):
   f=[x.strip() for x in line.split(';')[0].split(',')];scales.setdefault(tuple(map(int,f[:2])),[]).append(float(f[8]) if len(f)>8 and f[8] else 1)
 cycle_file=J/'art'/slug/'form-cycles-packing.json';cycles=json.loads(cycle_file.read_text())['cycles'] if cycle_file.exists() else []
 for group,form in body.items():
  key=tuple(form['key'])
  if key==tuple(r['key']) or int(group) in [62500,8793]:continue
  if key not in source.keys or key not in scales:continue
  index=source.keys[key];im=source.decode(index);name=slug+'-'+group+'.png';im.save(O/'sprites'/name);s=collections.Counter(scales[key]).most_common(1)[0][0]*r['cns_scale'][1]*320/r['width'];b=im.getbbox()
  cycle=next((c for c in cycles if c['source_group']==int(group)),None)
  labels={'rimuru':{'8791':'Rimuru / Demon Lord','8790':'Rimuru / Slime'},'jinwoo':{'61001':'Jinwoo / Igris','61002':'Jinwoo / Beru','61003':'Jinwoo / Iron','61004':'Jinwoo / Tank'}}
  label=cycle['label'] if cycle else labels.get(slug,{}).get(group,slug.replace('-',' ').title()+' alternate body')
  entry=dict(slug=slug,label=label,neutral=dict(file='sprites/'+name,axis=source.headers[index][4:6],scale=s,height=round((b[3]-b[1])*s,2)),role='alternate body',walk=None)
  if cycle:entry['walk']=dict(folder=f'../jus-upgrade/art/{slug}/cycles/{group}',frames=cycle['frames'],scale=cycle['air_scale'][1]*r['cns_scale'][1]*320/r['width'])
  items.append(entry)
 del source
