(O/'review-data.json').write_text(json.dumps(data,indent=2))
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cid redesign and JUS size fixes</title><style>*{box-sizing:border-box}body{margin:0;background:#111824;color:#eef2fa;font:16px/1.6 system-ui}main{max-width:1400px;margin:auto;padding:24px}a{color:#acd9ff}p{max-width:950px;color:#c2cedc}h1{line-height:1.2}section{background:#1c2839;padding:20px;margin:20px 0;border-radius:12px}.compare{display:flex;gap:20px;flex-wrap:wrap}.compare figure{flex:1 1 240px;margin:0}.compare img{height:350px;max-width:100%;object-fit:contain}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:8px}.card{background:#121d2c;text-align:center;padding:8px;border-radius:8px}.card canvas{width:210px;height:290px;max-width:100%}small{display:block;color:#b8cadc}button,select{font:inherit;padding:8px;background:#2b3a50;color:white;border:1px solid #6482a0;max-width:100%;margin:4px}#motion{width:600px;max-width:100%;background:#111b29}details{margin:14px 0}details img{max-width:100%}</style><main><h1>Cid redesign and consistent JUS sizes</h1><p>All 23 manga/manhwa fighters use compact gameplay sizes. Adult bodies are close in height; children, slime and pet forms stay smaller. Walking is calibrated against each body instead of changing character size. These are gameplay proportions, not a canon height chart.</p><p>The earlier roster comparison incorrectly multiplied the character scale twice for nine fighters. This page and the current roster viewer read the installed AIR, CNS and local coordinate values directly.</p><section id="cid"><h2>Cid / Shadow redesign</h2><p>Flatter cel shadows, a clearer youthful face, broad cloak shapes and restrained gold detail. All 56 Cid drawings and both HUD portrait slots are replaced. Existing moves, voices, effects and supporting characters remain. <a href="../characters/cid/art/redesign-v7/requests.json">Exact generation prompts</a> · <a href="https://shadow-garden.jp/1st/character/chara1.php">Official identity/costume reference</a></p><div class="compare"><figure><img src="../characters/cid/art/illustrated-v1/hero.png" alt="Previous Cid artwork"><figcaption>Previous artwork</figcaption></figure><figure><img src="../characters/cid/art/redesign-v7/hero.png" alt="Redesigned Cid in flat anime style"><figcaption>Redesigned Cid</figcaption></figure><figure><img src="../characters/cid/art/redesign-v7/portrait.png" alt="New Cid portrait"><figcaption>New portrait</figcaption></figure></div></section><section><h2>Current roster, shared world scale</h2><p>Every card uses the same scale and foot baseline. Pictures are decoded from the actual installed sprite archives.</p><div class="grid" id="lineup"></div></section><section><h2>Standing / walking / alternate bodies</h2><select id="actor"></select><button id="pause">Pause</button><button id="step">Next pose</button><button id="flip">Face left</button><p id="note"></p><canvas id="motion" width="600" height="320"></canvas></section><section><h2>Redesigned Cid animation sheets</h2>SHEETS</section><p>Fresh game recordings are deferred. Existing recordings on older character pages show the previous art and proportions. <a href="installation.json">Installed size changes</a> · <a href="policy.json">Gameplay size policy</a> · <a href="../characters/cid/art/redesign-v7/installation.json">Cid art installation</a> · <a href="../roster.html">Manga vs Manhwa roster</a></p></main><script>const data=DATA,items=data.items,cache={};function img(path){if(!cache[path]){const im=new Image;im.src=path;cache[path]=im}return cache[path]}function drawActor(c,a,x,y,s=4,flip=false){const im=img(a.file);if(!im.complete||!im.naturalWidth)return;c.save();c.translate(x,y);if(flip)c.scale(-1,1);c.drawImage(im,-a.axis[0]*a.scale*s,-a.axis[1]*a.scale*s,im.width*a.scale*s,im.height*a.scale*s);c.restore()}for(const a of data.fighters){const card=document.createElement('article');card.className='card';card.innerHTML='<b>'+a.label+'</b><small>'+a.role+'</small><canvas width="210" height="290"></canvas>';document.querySelector('#lineup').append(card);const im=img(a.neutral.file),draw=()=>{const c=card.querySelector('canvas').getContext('2d');c.clearRect(0,0,210,290);c.strokeStyle='#63809c';c.beginPath();c.moveTo(0,270);c.lineTo(210,270);c.stroke();drawActor(c,a.neutral,105,270)};if(im.complete)draw();else im.onload=draw}for(const [i,a]of items.entries()){const o=document.createElement('option');o.value=i;o.textContent=a.label;document.querySelector('#actor').append(o)}let frames=[],frame=0,paused=false,flip=false,last=0,current=0;function select(){current=Number(document.querySelector('#actor').value);const a=items[current];frame=0;frames=a.walk?a.walk.frames.map((f,i)=>({file:a.walk.folder+'/'+(a.walk.indices?String(a.walk.indices[i]).padStart(2,'0'):('walk-'+String(i).padStart(2,'0')))+'.png',axis:f.axis,scale:a.walk.scale})):[];frames.forEach(f=>img(f.file));document.querySelector('#note').textContent='Left: installed standing pose. Right: '+(frames.length?'eight walk drawings at the same world scale.':'same standing pose; existing animation retained.')+' Standing height '+a.neutral.height+' world units.'}document.querySelector('#actor').onchange=select;document.querySelector('#pause').onclick=()=>{paused=!paused;document.querySelector('#pause').textContent=paused?'Play':'Pause'};document.querySelector('#step').onclick=()=>{paused=true;document.querySelector('#pause').textContent='Play';frame=(frame+1)%Math.max(frames.length,1)};document.querySelector('#flip').onclick=()=>{flip=!flip;document.querySelector('#flip').textContent=flip?'Face right':'Face left'};function loop(t){if(!paused&&t-last>=1000/30){frame=(frame+1)%Math.max(frames.length,1);last=t}const c=document.querySelector('#motion').getContext('2d');c.clearRect(0,0,600,320);c.strokeStyle='#63809c';c.beginPath();c.moveTo(0,290);c.lineTo(600,290);c.stroke();drawActor(c,items[current].neutral,150,290,4,flip);drawActor(c,frames[frame]||items[current].neutral,450,290,4,flip);requestAnimationFrame(loop)}select();requestAnimationFrame(loop);</script></html>'''
